<?php defined('BASEPATH') OR exit('No direct script access allowed');$source=$session['question_source']??'bank_all';$sourceLabels=['bank_all'=>'Bank soal sesuai filter','selected'=>'Soal bank yang dipilih','session_only'=>'Soal khusus sesi'];$difficulty=['easy'=>'Mudah','medium'=>'Sedang','hard'=>'Sulit'];$letters=['A','B','C','D','E']; ?>
<div class="page-header"><div class="container-xl"><div class="row align-items-center"><div class="col"><div class="page-pretitle">Latihan Soal · Soal Terhubung</div><h1 class="page-title"><?=html_escape($session['title']);?></h1><p class="text-secondary mb-0"><code><?=html_escape($session['code']);?></code> · <?=html_escape($sourceLabels[$source]??$source);?> · <?=count($questions);?> soal tersedia</p></div><div class="col-auto d-flex gap-2"><a href="<?=base_url('quiz-sessions/edit/'.(int)$session['id'].'?tab=questions');?>" class="btn btn-outline-primary"><i class="ti ti-settings me-1"></i>Atur Sumber Soal</a><a href="<?=base_url('quiz-sessions');?>" class="btn btn-outline-secondary"><i class="ti ti-arrow-left me-1"></i>Daftar Sesi</a></div></div></div></div>
<div class="page-body"><div class="container-xl"><div class="alert alert-info"><i class="ti ti-info-circle me-1"></i><?php if($source==='bank_all'):?>Sesi mengambil maksimal <strong><?= (int)$session['question_count'];?> soal</strong> secara acak dari kumpulan di bawah sesuai filter sesi.<?php else:?>Urutan berikut mengikuti hubungan soal yang tersimpan pada sesi. Saat dimainkan, jumlah soal tetap mengikuti pengaturan sesi.<?php endif;?></div><div class="row g-3"><?php foreach($questions as $index=>$q):?><div class="col-12"><article class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-start gap-2"><div class="d-flex gap-2 flex-wrap"><span class="badge bg-dark text-white">Soal <?=$index+1;?></span><span class="badge bg-blue-lt"><?=html_escape($q['subject_name']??'-');?></span><span class="badge bg-cyan-lt"><?=html_escape($q['grade_name']??'-');?></span><span class="badge bg-orange-lt"><?=html_escape($difficulty[$q['difficulty']]??$q['difficulty']);?></span><span class="badge <?=!empty($q['is_session_only'])?'bg-purple-lt':'bg-secondary-lt';?>"><?=!empty($q['is_session_only'])?'Khusus sesi':'Bank umum';?></span><?php if(empty($q['is_active'])):?><span class="badge bg-red-lt">Nonaktif</span><?php endif;?></div><code>#<?= (int)$q['id'];?></code></div><h3 class="h4 mt-3 mb-2"><?=html_escape($q['question_text']);?></h3><?php if(!empty($q['question_image'])):?><img src="<?=base_url(ltrim($q['question_image'],'/'));?>" alt="Gambar soal" class="img-fluid rounded border mb-3" style="max-height:320px"><?php endif;?><?php if($q['type']==='multiple_choice'):?><div class="row g-2"><?php foreach($q['options'] as $option):$correct=(int)$q['correct_option_index']===(int)$option['option_index'];?><div class="col-md-6"><div class="p-2 rounded border <?=$correct?'bg-success-lt border-success':'';?>"><span class="badge <?=$correct?'bg-success text-white':'bg-secondary-lt';?> me-2"><?=$letters[(int)$option['option_index']]??$option['option_index'];?></span><span class="<?=$correct?'fw-bold text-success':'';?>"><?=html_escape($option['option_text']);?></span><?php if(!empty($option['option_image'])):?><img src="<?=base_url(ltrim($option['option_image'],'/'));?>" class="d-block img-fluid rounded mt-2" style="max-height:150px" alt="Gambar pilihan"><?php endif;?></div></div><?php endforeach;?></div><?php else:?><span class="badge bg-purple-lt">Essay</span><?php endif;?><?php if(!empty($q['explanation'])):?><div class="alert alert-light mt-3 mb-0"><i class="ti ti-bulb me-1"></i><?=nl2br(html_escape($q['explanation']));?></div><?php endif;?></div></article></div><?php endforeach;?></div><?php if(!$questions):?><div class="card"><div class="card-body text-center text-secondary py-5"><i class="ti ti-library-off fs-1 d-block mb-2"></i>Belum ada soal yang terhubung atau sesuai dengan filter sesi ini.</div></div><?php endif;?></div></div>
